`Limit` هو struct و`Wallet` هو class. اقرأ المقطع وتوقّع السطر الوحيد الذي يطبعه.

```swift
import Foundation

struct Limit {
    var amount: Decimal
}

final class Wallet {
    var balance: Decimal
    init(balance: Decimal) { self.balance = balance }
}

var food = Limit(amount: 300)
var fun = food
fun.amount = 100

let mine = Wallet(balance: 500)
let shared = mine
shared.balance -= 50

print(food.amount, fun.amount, mine.balance)
```
